def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    my_c = 0
    my_d = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1

    d_opp = n - opp_c
    if opp_c == 0:
        return 'D'

    coop_rate = opp_c / n

    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    recent_d = 0
    rs = n - 12
    if rs < 0:
        rs = 0
    for i in range(rs, n):
        if history[i][1] == 'D':
            recent_d += 1

    attempts = 0
    my_d_in_streak = 0
    if opp_d_streak > 0:
        for i in range(n - opp_d_streak, n):
            if history[i][0] == 'C':
                attempts += 1
            else:
                my_d_in_streak += 1

    c_tot = c_to_c = 0
    d_tot = d_to_c = 0
    rc_tot = rc_c = 0
    rd_tot = rd_c = 0

    pc = {'CC': 0, 'CD': 0, 'DC': 0, 'DD': 0}
    pt = {'CC': 0, 'CD': 0, 'DC': 0, 'DD': 0}

    r_start = n - 17
    if r_start < 0:
        r_start = 0

    for i in range(n - 1):
        mine = history[i][0]
        oppc = history[i][1]
        nxt = history[i + 1][1]

        if mine == 'C':
            c_tot += 1
            if nxt == 'C':
                c_to_c += 1
        else:
            d_tot += 1
            if nxt == 'C':
                d_to_c += 1

        s = mine + oppc
        pt[s] += 1
        if nxt == 'C':
            pc[s] += 1

        if i >= r_start:
            if mine == 'C':
                rc_tot += 1
                if nxt == 'C':
                    rc_c += 1
            else:
                rd_tot += 1
                if nxt == 'C':
                    rd_c += 1

    prior_C = coop_rate
    if prior_C < 0.15:
        prior_C = 0.15
    if prior_C > 0.95:
        prior_C = 0.95

    prior_D = 0.32 if my_d == 0 else 0.36

    p_C_after_C = (
        (c_to_c + 1.4 * rc_c + 2.5 * prior_C) /
        (c_tot + 1.4 * rc_tot + 2.5)
    )
    p_C_after_D = (
        (d_to_c + 1.4 * rd_c + 1.1 * prior_D) /
        (d_tot + 1.4 * rd_tot + 1.1)
    )

    if recent_d >= 6:
        p_C_after_C *= 0.82
        if p_C_after_C > 0.75:
            p_C_after_C = 0.75

    diff = p_C_after_C - p_C_after_D

    state = last_me + last_opp
    if state == 'CC':
        pr_state = max(0.35, min(0.95, coop_rate))
    elif state == 'CD':
        pr_state = 0.65 if coop_rate > 0.65 else 0.25
    elif state == 'DC':
        pr_state = p_C_after_D if d_tot > 0 else max(0.50, coop_rate)
    else:
        pr_state = 0.25 if coop_rate > 0.5 else 0.15

    base_p = p_C_after_C if last_me == 'C' else p_C_after_D
    p_now = 0.65 * base_p + 0.35 * ((pc[state] + pr_state) / (pt[state] + 1.0))

    if p_now < 0.05:
        p_now = 0.05
    elif p_now > 0.95:
        p_now = 0.95

    rem = 100 - n

    if coop_rate < 0.22 and d_opp >= 6:
        return 'D'

    if opp_d_streak >= 2:
        if last_me == 'C':
            if attempts >= 2:
                return 'D'
            if p_C_after_C < 0.50 or recent_d >= 9:
                return 'D'
            return 'C'
        else:
            if opp_d_streak <= 4 and coop_rate > 0.28 and recent_d < 10:
                return 'C'
            if p_C_after_C > 0.62 and opp_d_streak <= 5 and recent_d < 5:
                return 'C'
            return 'D'

    if rem <= 3 and last_me == 'C' and last_opp == 'C' and coop_rate >= 0.80 and recent_d == 0:
        return 'D'

    if last_opp == 'C':
        if rem > 40:
            thr = 0.18
        elif rem > 20:
            thr = 0.22
        elif rem > 10:
            thr = 0.27
        elif rem > 4:
            thr = 0.34
        else:
            thr = 0.55

        if p_C_after_D >= 0.58 and diff <= 0.22:
            return 'D'

        if rem <= 6 and coop_rate > 0.78 and recent_d == 0 and p_C_after_D > 0.45:
            return 'D'

        if diff >= thr:
            return 'C'

        if coop_rate > 0.70 and p_C_after_D < 0.45 and diff > -0.10:
            return 'C'

        if p_now > 0.52 and p_C_after_D > 0.30 and diff < thr + 0.08:
            return 'D'

        return 'C' if coop_rate > 0.75 else 'D'

    if last_me == 'C':
        if diff >= 0.25 and p_C_after_C > 0.55:
            return 'C'
        if coop_rate > 0.70 and recent_d <= 2:
            return 'C'
        if rem <= 4 and p_C_after_D > 0.30:
            return 'D'
        return 'D'

    if diff >= 0.18 and p_C_after_C > 0.45:
        return 'C'

    return 'D'
